param([switch]$Live)
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot '..\CodexFloatingWidget.ps1') -TestMode
$out=Join-Path $PSScriptRoot 'artifacts';New-Item -ItemType Directory -Path $out -Force|Out-Null
$script:Checks=0
function Assert($condition,[string]$message){if(-not $condition){throw "FAIL: $message"};$script:Checks++}
function Click($button){$button.RaiseEvent([Windows.RoutedEventArgs]::new([Windows.Controls.Button]::ClickEvent))}
$script:Accounts=@([pscustomobject]@{id='a';name='demoaccount@example.com';email='demoaccount@example.com';plan_type='plus'},[pscustomobject]@{id='b';name='testaccount@example.org';email='testaccount@example.org';plan_type='plus'},[pscustomobject]@{id='c';name='workaccount@example.net';email='workaccount@example.net';plan_type='prolite'})
$script:ActiveId='a';$script:Now=1800000000
$values=@(@(35,58,8280,280800),@(10,22,14700,439200),@(70,45,6120,201600))
for($i=0;$i -lt 3;$i++){$v=$values[$i];Apply-UsageResult $script:Accounts[$i].id ([pscustomobject]@{primary_used_percent=$v[0];secondary_used_percent=$v[1];primary_resets_at=$script:Now+$v[2];secondary_resets_at=$script:Now+$v[3]}) ''}
$window.Left=80;$window.Top=80;$window.Show();Update-View
foreach($upper in @($true,$false)){foreach($p in @(0,1,30,50,65,99,100)){$g=Get-ArcGeometry $p $upper;if($p -eq 0){Assert ($null -eq $g) 'zero has no colored overlay';continue};$f=$g.Figures[0];$seg=$f.Segments[0];Assert ($seg.Point.X -eq 160 -and $seg.Point.Y -eq 84) 'arc ends at right';$angle=[Math]::Atan2($f.StartPoint.Y-84,$f.StartPoint.X-84);Assert ([Math]::Abs([Math]::Abs($angle)/[Math]::PI*100-$p) -lt 0.00001) 'exact independent proportion';Assert (($upper -and $f.StartPoint.Y -le 84.00001) -or (-not $upper -and $f.StartPoint.Y -ge 83.99999)) 'correct half';if($p -eq 30){Assert ($f.StartPoint.X -gt 84) '30% entirely on right'}}}
$canvas=$CurrentHost.Children[0].Children[0];$track=$canvas.Children[0];Assert ($track -is [Windows.Shapes.Ellipse] -and $track.Width -eq $track.Height) 'closed circular base'
Export-Render (Join-Path $out '01-collapsed.png');$y=$ToggleButton.TranslatePoint([Windows.Point]::new(0,0),$window).Y
Click $ToggleButton;Assert $script:Expanded 'toggle click expands';Assert ($ExtraHost.Children.Count -eq 2) 'two other accounts';Assert ($ToggleButton.TranslatePoint([Windows.Point]::new(0,0),$window).Y -eq $y) 'toggle remains fixed';Export-Render (Join-Path $out '02-expanded.png')
$b=@($ExtraHost.Children[0].Children[0].Children|Where-Object {$_ -is [Windows.Controls.Button]})[0];Click $b;Assert ($script:SwitchState.TargetId -eq 'b') 'real button routes exact ID';Start-AccountSwitch 'c';Assert ($script:TestSwitchLaunchCount -eq 1 -and $script:SwitchState.TargetId -eq 'b') 'double clicks suppressed'
foreach($panel in $ExtraHost.Children){$b=@($panel.Children[0].Children|Where-Object {$_ -is [Windows.Controls.Button]})[0];Assert (-not $b.IsEnabled) 'all switches disabled while switching'}
Finish-Switch $true '';Assert ($script:ActiveId -eq 'b' -and -not $script:Expanded) 'success promotes and collapses';Export-Render (Join-Path $out '03-switched.png')
Click $ToggleButton;$b=@($ExtraHost.Children[1].Children[0].Children|Where-Object {$_ -is [Windows.Controls.Button]})[0];Click $b;Assert ($script:SwitchState.TargetId -eq 'c') 'third account button routes';Finish-Switch $false '模拟失败';Assert ($script:Expanded -and $script:ActiveId -eq 'b' -and $script:SwitchError -eq '模拟失败') 'failure remains expanded and sticky'
$previous=$script:Usage.a.Data;Apply-UsageResult 'a' $null 'offline';Assert ($script:Usage.a.Data -eq $previous -and $script:Usage.a.Error -eq 'offline') 'cache preserved on failure';Apply-UsageResult 'c' ([pscustomobject]@{primary_used_percent=$null;primary_resets_at=$null;secondary_used_percent=48;secondary_resets_at=1800300000}) '';Update-View;$dial=New-Dial $script:Accounts[2];$texts=@($dial.Children[0].Children|Where-Object {$_ -is [Windows.Controls.TextBlock]}|ForEach-Object Text);Assert ($texts -contains '5h —' -and $texts -contains '重置时间未知') 'null stays unknown';Assert ($script:Usage.b.Error -eq '') 'other account unaffected';Export-Render (Join-Path $out '04-error-unknown.png')
$script:Status='';$script:Expanded=$false;Update-View;$area=Get-WorkArea;$window.Top=$area.Bottom-$window.Height;Click $ToggleButton;Assert ($ExtraScroll.ActualHeight -ge 118) 'bottom edge useful scroll viewport';Assert ($window.Top+$window.Height -le $area.Bottom+1) 'expanded within workarea';$ExtraScroll.ScrollToVerticalOffset(140);$window.UpdateLayout();$before=$ExtraScroll.VerticalOffset;Update-View;$window.UpdateLayout();Assert ([Math]::Abs($ExtraScroll.VerticalOffset-$before) -lt 1) 'scroll preserved'
Update-Lifecycle $false;Assert (-not $window.IsVisible) 'Codex close hides';Update-Lifecycle $true;Assert $window.IsVisible 'Codex reopen restores';$script:UserHidden=$true;$window.Hide();Update-Lifecycle $true;Assert (-not $window.IsVisible) 'manual hide persists';Update-Lifecycle $false;Update-Lifecycle $true;Assert $window.IsVisible 'new Codex session restores hidden widget'
# Async worker returns independently; use real background pipeline and stale list generation.
Begin-Worker 'list' '' { [pscustomobject]@{Accounts=@();ActiveId='stale'} } @();$script:Generation++;Start-Sleep -Milliseconds 100;Poll-Workers;Assert ($script:ActiveId -eq 'b') 'stale list cannot overwrite switched account'
if($Live){$script:Accounts=@();$script:Usage=@{};$script:Aliases=@{};$script:ActiveId='';$script:SwitchError='';$script:Status='';$script:Now=[DateTimeOffset]::UtcNow.ToUnixTimeSeconds();$window.Left=80;$window.Top=80;Refresh-Widget;$deadline=[datetime]::Now.AddSeconds(60);while($script:Jobs.Count -and [datetime]::Now -lt $deadline){Start-Sleep -Milliseconds 100;Poll-Workers};Assert ($script:Accounts.Count -eq 3) 'live 3 accounts';Assert ($script:Usage.Count -eq 3) 'live 3 independent usage results';Assert (@($script:Usage.Values|Where-Object Error).Count -eq 0) 'live usage requests successful';$script:Expanded=$true;Update-View;Export-Render (Join-Path $out '05-live-expanded.png');$script:Expanded=$false;Update-View;Export-Render (Join-Path $out '06-live-collapsed.png');$i=0;foreach($a in $script:Accounts){$i++;$u=$script:Usage[[string]$a.id].Data;[pscustomobject]@{Account=$i;PrimaryUsed=$u.primary_used_percent;WeeklyUsed=$u.secondary_used_percent;PrimaryResetKnown=($null -ne $u.primary_resets_at);WeeklyResetKnown=($null -ne $u.secondary_resets_at)}|ConvertTo-Json -Compress}}
$script:AllowClose=$true;$window.Close();$application.Shutdown();"PASS $script:Checks checks"
